const input = $input.first().json.body ?? $input.first().json;
if (typeof input.content !== 'string' || !input.content.trim()) {
  throw new Error('A non-empty content string is required.');
}
if (input.content_type && input.content_type !== 'text') {
  throw new Error('Only text submissions are supported.');
}
return [{ json: {
  content: input.content,
  rules: input.rules ?? {},
  employee_name: input.employee_name ?? 'Employee'
} }];

const response = $input.first().json;
const content = response.choices?.[0]?.message?.content;
if (typeof content !== 'string') throw new Error('OpenAI did not return an analysis.');
const result = JSON.parse(content);
if (!['Approved', 'Flagged'].includes(result.status)) throw new Error('OpenAI returned an unknown status.');
if (!Number.isInteger(result.compliance_score) || result.compliance_score < 0 || result.compliance_score > 100) throw new Error('OpenAI returned an invalid compliance score.');
if (typeof result.ai_feedback !== 'string' || !result.ai_feedback.trim() || !Array.isArray(result.violations) || !Array.isArray(result.suggested_corrections)) throw new Error('OpenAI returned an invalid analysis shape.');
return [{ json: result }];
